def countAnagramWindows(s, p):
    n, m = len(s), len(p)
    if m > n:
        return 0
    bal = {}
    for c in p:
        bal[c] = bal.get(c, 0) + 1
    nonzero = len(bal)
    count = 0

    def shift(c, d):
        nonlocal nonzero
        before = bal.get(c, 0)
        after = before + d
        bal[c] = after
        if before == 0 and after != 0:
            nonzero += 1
        elif before != 0 and after == 0:
            nonzero -= 1

    for i in range(n):
        shift(s[i], -1)
        if i >= m:
            shift(s[i - m], 1)
        if i >= m - 1 and nonzero == 0:
            count += 1
    return count
